const cards = document.querySelectorAll('[id^="mntl-card-list-card--extendable"]');
const results = [];
for (const card of cards) {
  const titleEl = card.querySelector('.mntl-recipe-card-meta__title, [class*="recipe-card__title"]');
  const title = titleEl ? titleEl.textContent.trim() : '';
  const ratingContainer = card.querySelector('[id^="mntl-recipe-star-rating"]');
  let rating = '';
  let reviewCount = '';
  if (ratingContainer) {
    rating = ratingContainer.getAttribute('data-rating') || ratingContainer.getAttribute('aria-label') || '';
    const countEl = ratingContainer.parentElement.querySelector('.mntl-recipe-card-meta__rating-count-number, [class*="rating-count"]');
    // Find sibling div with rating number
    const parent = ratingContainer.parentElement;
    const divs = parent.querySelectorAll('div');
    for (const d of divs) {
      const t = d.textContent.trim();
      if (/^\d+(\.\d+)?$/.test(t)) {
        reviewCount = t;
        break;
      }
    }
  }
  if (!rating) {
    // Try to get from stars via aria-label or fill amount
    const stars = card.querySelectorAll('[id^="mntl-recipe-star-rating"] svg');
    if (stars.length > 0) {
      const fillPercent = Array.from(stars).map(s => {
        const style = s.getAttribute('style') || '';
        const match = style.match(/--rating:([\d.]+)/);
        if (match) return parseFloat(match[1]);
        const fill = s.getAttribute('fill') || '';
        return fill;
      });
      rating = fillPercent.join(',');
    }
  }
  results.push({ title, rating, reviewCount, url: card.href });
}
return results;

const cards = document.querySelectorAll('[id^="mntl-card-list-card--extendable"]');
const results = [];
for (const card of cards) {
  // Get title
  const titleEl = card.querySelector('.mntl-recipe-card-meta__title');
  const title = titleEl ? titleEl.textContent.trim() : '';

  // Get rating container and find the actual rating value via aria-label or inner text
  const ratingContainer = card.querySelector('[id^="mntl-recipe-star-rating"]');
  let rating = '';
  if (ratingContainer) {
    rating = ratingContainer.getAttribute('data-rating') || 
             ratingContainer.getAttribute('aria-label') || 
             ratingContainer.getAttribute('title') || '';
    if (!rating) {
      // Look at the SVG stars for fill information
      const stars = ratingContainer.querySelectorAll('svg');
      const ratings = Array.from(stars).map(s => {
        return s.getAttribute('data-rating') || s.getAttribute('aria-label') || s.outerHTML.substring(0,200);
      });
      rating = 'stars:' + ratings.join('|');
    }
  }

  // Get review count - find the next div sibling
  let reviewCount = '';
  if (ratingContainer) {
    const parent = ratingContainer.parentElement;
    const divs = parent.querySelectorAll('div');
    for (const d of divs) {
      if (d === ratingContainer) continue;
      const t = d.textContent.trim();
      if (/^\d+/.test(t)) {
        reviewCount = t;
        break;
      }
    }
  }

  results.push({ title, rating, reviewCount, url: card.href });
}
return results;

const cards = document.querySelectorAll('[id^="mntl-card-list-card--extendable"]');
const results = [];
for (const card of cards) {
  const titleEl = card.querySelector('.mntl-recipe-card-meta__title');
  const title = titleEl ? titleEl.textContent.trim() : '';
  const ratingContainer = card.querySelector('[id^="mntl-recipe-star-rating"]');

  let ratingText = '';
  if (ratingContainer) {
    const fillEls = ratingContainer.querySelectorAll('[style*="--rating"]');
    const ratings = [];
    for (const f of fillEls) {
      const style = f.getAttribute('style') || '';
      const m = style.match(/--rating:\s*([\d.]+)/);
      if (m) ratings.push(parseFloat(m[1]));
    }
    if (ratings.length > 0) {
      const total = ratings.reduce((a,b) => a+b, 0);
      ratingText = total.toFixed(2);
    } else {
      ratingText = ratingContainer.getAttribute('aria-label') || ratingContainer.getAttribute('data-rating') || '';
    }
  }

  let reviewCount = '';
  if (ratingContainer) {
    const parent = ratingContainer.parentElement;
    const divs = parent.querySelectorAll('div');
    for (const d of divs) {
      if (d === ratingContainer) continue;
      const t = d.textContent.trim();
      if (/^\d+(\.\d+)?$/.test(t)) {
        reviewCount = t;
        break;
      }
    }
  }

  results.push({ title, rating: ratingText, reviewCount, url: card.href });
}
return JSON.stringify(results, null, 2);
